27	  typeof value === 'string' && Object.prototype.hasOwnProperty.call(INDUSTRY_PHONE, value);
28	
29	function StaticPhoneShell({ className, style }: Pick<LandingPhoneMountProps, 'className' | 'style'>) {
30	  return (
31	    <div
32	      className={className}
33	      data-demo-scene="shell"
34	      role="img"
35	      aria-label="taptpay app preview"
36	      style={{
37	        width: 390,
38	        height: 844,
39	        background: 'linear-gradient(158deg,#0a1656 0%,#040D6D 46%,#0b1a6e 100%)',
40	        ...style,
41	      }}
42	    />
43	  );
44	}
45	
46	class DeferredPhoneBoundary extends Component<
47	  { fallback: ReactNode; children: ReactNode },
48	  { failed: boolean }
49	> {
50	  state = { failed: false };
